// ============ 状态 ============
let current = 0;
let score = 0;
let submitted = false;
let records = {}; // idx -> {answer, stars, score, verdict, comment, teach, expect}
const SAVE_KEY = "etcpm-save-v1";
const $ = id => document.getElementById(id);

// ============ 工具函数 ============
function esc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");}
function starsHtml(n){
  let h="";
  for(let i=1;i<=3;i++){ h += i<=n ? '<svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2l2.9 6.3 6.9.8-5.1 4.7 1.4 6.8L12 17.2 5.9 20.6l1.4-6.8L2.2 9.1l6.9-.8L12 2z"/></svg>' : '<svg class="off" width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2l2.9 6.3 6.9.8-5.1 4.7 1.4 6.8L12 17.2 5.9 20.6l1.4-6.8L2.2 9.1l6.9-.8L12 2z"/></svg>'; }
  return h;
}
function toast(msg){const t=$("toast");t.textContent=msg;t.classList.add("show");clearTimeout(t._h);t._h=setTimeout(()=>t.classList.remove("show"),2000);}
function norm(s){return s.toLowerCase();}
function groupRatio(groups, text){
  let hit=0;
  groups.forEach(g=>{ if(g.some(k=>text.includes(k))) hit++; });
  return groups.length? hit/groups.length : 0;
}
const CN={一:1,二:2,三:3,四:4,五:5};
function parseLevels(t){
  let s=null,a=null,level=null;
  const t0=t.replace(/[，。、：:；;　\s]/g,"");
  const mSA=t0.match(/[sS][=＝]?\s*([1-5])[aA][=＝]?\s*([1-5])/);
  if(mSA){s=+mSA[1];a=+mSA[2];level=Math.max(s,a);}
  const mS=t0.match(/[sS][=＝]?\s*([1-5])/);
  if(mS&&s===null)s=+mS[1];
  const mA=t0.match(/[aA][=＝]?\s*([1-5])/);
  if(mA&&a===null)a=+mA[1];
  const mL=t0.match(/([1-5])\s*级/);
  if(mL)level=+mL[1];
  if(level===null&&s===null&&a===null){
    const mn=t0.match(/(^|[^\d])([1-5])([^\d]|$)/);
    if(mn)level=+mn[2];
  }
  const mcn=t0.match(/[一二三四五]级/);
  if(mcn&&level===null)level=CN[mcn[0][0]];
  return {s,a,level};
}
function confusionNote(custom, v){
  if(custom==="S" && /服务|中断|停摆|宕机|瘫痪|无法办理/.test(v) && !/数据|泄露|篡改|破坏|被盗/.test(v)){
    return "注意：你似乎在用「服务中断」来解释 S —— S 看数据、A 看服务，不要把两个要素搞混。";
  }
  if(custom==="A" && /数据|泄露|篡改|破坏|被盗/.test(v) && !/服务|中断|停摆|瘫痪|无法办理|停摆/.test(v)){
    return "注意：你似乎在用「数据出事」来解释 A —— A 看服务、S 看数据，不要把两个要素搞混。";
  }
  return "";
}

// ============ 评分引擎 ============
function evaluate(s, v){
  const text=norm(v);
  if(s.custom){
    const p=parseLevels(v);
    const lv = s.custom==="S" ? (p.s!==null?p.s:p.level) : s.custom==="A" ? (p.a!==null?p.a:p.level) : p.level;
    const ok = lv===s.expectedLevel;
    const ratio=groupRatio(s.groups,text);
    const conf=confusionNote(s.custom,v);
    let stars,score,verdict,comment;
    if(lv===null||lv===undefined){
      stars=1; score=Math.min(10,Math.round(3+3*ratio)); verdict="需要重读判定";
      comment="没有读到明确的等级数字。请按「S=? 级 / A=? 级 / 第X级（S?A?）」的格式作答，并写出理由。"+(conf?" "+conf:"");
    }else if(ok&&ratio>=0.6){
      stars=3; score=Math.min(10,Math.round(6+4*ratio)); verdict="判定优秀"; comment=s.good;
    }else if(ok){
      stars=2; score=Math.min(10,Math.round(6+4*ratio)); verdict="判定良好"; comment=s.mid;
    }else{
      stars=1; score=Math.min(10,Math.round(3+3*ratio)); verdict="判定有误"; comment=s.poor+(conf?" "+conf:"");
    }
    return {stars,score,verdict,comment,teach:s.teach,expect:s.expect};
  }
  const ratio=groupRatio(s.groups,text);
  const stars=ratio>=0.75?3:ratio>=0.5?2:1;
  const score=Math.round(s.base*ratio);
  const verdict=stars===3?"判定优秀":stars===2?"判定良好":"需加强";
  const comment=stars===3?s.good:stars===2?s.mid:s.poor;
  return {stars,score,verdict,comment,teach:s.teach,expect:s.expect};
}

// ============ 渲染 ============
function currentStage(){return STEPS[current].stage;}
function renderMap(){
  const row=$("stageRow"); row.innerHTML="";
  const cs=currentStage();
  STAGES.forEach((st,si)=>{
    const col=document.createElement("div");
    col.className="stage-col"+(si===cs?" active":"");
    const steps=STEPS.map((s,i)=>({s,i})).filter(x=>x.s.stage===si);
    let dots="<div class='steps-dots'>";
    steps.forEach(({i})=>{
      let cls="step-dot";
      if(records[i]){cls+=" done reviewable";}
      else if(i===current){cls+=" cur";}
      else if(i>current){cls+=" locked";}
      dots+=`<div class="${cls}" data-idx="${i}" title="${esc(STEPS[i].title)}">${records[i]?"✓":(i+1)}</div>`;
    });
    dots+="</div>";
    col.innerHTML=`<div class="st-name"><span class="st-dot" style="background:${st.color}"></span>${st.name}</div>${dots}`;
    row.appendChild(col);
  });
  row.querySelectorAll(".step-dot.reviewable").forEach(d=>{
    d.addEventListener("click",()=>openReview(+d.dataset.idx));
  });
}
function renderStep(){
  const s=STEPS[current];
  $("scNum").textContent=current+1;
  $("scTitle").textContent=s.title;
  const tag=$("scStage"); tag.textContent=STAGES[s.stage].name; tag.className="tag tag-stage-"+s.stage;
  $("scScene").textContent=s.scene;
  $("scTask").textContent=s.task;
  $("hintText").textContent=s.hint;
  $("hintText").classList.remove("show");
  $("answerInput").value="";
  $("answerInput").disabled=false;
  $("feedbackSlot").innerHTML="";
  $("btnSubmit").disabled=false;
  $("stageProg").textContent=`关卡 ${current+1} / ${STEPS.length}`;
  $("stageChip").textContent="当前阶段："+STAGES[s.stage].name;
  $("stageChip").style.display="inline-flex";
  $("scoreVal").textContent=score;
  renderMap();
  $("answerInput").focus();
  window.scrollTo({top:0,behavior:"smooth"});
}
function renderFeedback(rec, readOnly){
  const s=STEPS[current];
  const cls=rec.stars===3?"good":rec.stars===2?"mid":"poor";
  const bookIcon='<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg>';
  $("feedbackSlot").innerHTML=`
  <div class="feedback ${cls}">
    <div class="fb-head">
      <span class="stars">${starsHtml(rec.stars)}</span>
      <span class="fb-verdict">${rec.verdict}</span>
      <span class="fb-score">得分 <b>${rec.score}</b> / ${s.base}</span>
    </div>
    <div class="fb-comment">${esc(rec.comment)}
      <span class="qa"><b>你的答案：</b>${esc(rec.answer)}</span>
    </div>
    <div class="teach-card"><div class="tc-lb">${bookIcon} 知识点讲解</div><p>${rec.teach}</p><p style="color:#8FA7C3;margin-top:6px">参考要点：${rec.expect}</p></div>
    <div class="fb-next">
      <button class="btn-ghost" id="btnRetry">重新作答</button>
      <button class="btn-next" id="btnNext">${current===STEPS.length-1?"生成交付报告":"下一关 →"}</button>
    </div>
  </div>`;
  $("btnNext").addEventListener("click",()=>{
    if(current===STEPS.length-1){openReport();}else{current++;submitted=false;save();renderStep();}
  });
  const retry=$("btnRetry");
  if(retry)retry.addEventListener("click",()=>{
    score-=rec.score; records[current]=null; delete records[current]; submitted=false; save();
    $("feedbackSlot").innerHTML=""; $("answerInput").value=rec.answer; $("answerInput").disabled=false; $("btnSubmit").disabled=false; $("scoreVal").textContent=score;
    renderMap(); $("answerInput").focus();
  });
  if(readOnly){$("answerInput").disabled=true;$("btnSubmit").disabled=true;}
  $("scoreVal").textContent=score;
}

// ============ 提交 ============
function onSubmit(){
  const v=$("answerInput").value.trim();
  if(!v){toast("请先输入你的答案再提交");return;}
  const s=STEPS[current];
  const res=evaluate(s,v);
  if(records[current])score-=records[current].score;
  records[current]=res; score+=res.score; submitted=true;
  save();
  $("answerInput").disabled=true; $("btnSubmit").disabled=true;
  renderFeedback(records[current],false);
}

// ============ 复盘 ============
function openReview(idx){
  const r=records[idx]; if(!r)return;
  const s=STEPS[idx];
  $("reviewBody").innerHTML=`
    <div class="rev-item">
      <div class="ri-meta"><span class="stars">${starsHtml(r.stars)}</span><span class="fb-verdict" style="color:${r.stars===3?"#3DDC97":r.stars===2?"#F5B93E":"#F87171"}">${r.verdict}</span><span style="color:#8FA7C3;font-size:12px">得分 ${r.score}/${s.base}</span></div>
      <div class="ri-q">第${idx+1}关 · ${s.title}</div>
      <div class="ri-a"><b style="color:#4CC3FF">你的答案：</b>${esc(r.answer)}</div>
      <div class="ri-f"><b style="color:#F5B93E">点评：</b>${esc(r.comment)}</div>
      <div class="ri-f" style="margin-top:6px"><b style="color:#2DD4BF">要点：</b>${r.expect}</div>
    </div>`;
  $("reviewMask").classList.remove("hidden");
}

// ============ 报告 ============
function rankInfo(){
  const pct=score/(STEPS.length*10);
  if(pct>=0.85)return {t:"金牌项目经理 · 等保测评专家",c:"#F5B93E",d:"你已完整掌握从接单、定级、编制方案到报告交付的全流程，具备独立带队开展等保测评的能力。定级环节的 S/A 判定逻辑清晰，标准依据引用规范——这是顶级测评项目经理的素质。"};
  if(pct>=0.7)return {t:"银牌项目经理 · 测评骨干",c:"#C0CCDA",d:"你已经能独立走完测评全流程，多数关卡判定准确。建议重点回看 1~2 星关卡，把定级判定矩阵与方案六要素再巩固一遍，向金牌冲刺。"};
  if(pct>=0.55)return {t:"铜牌项目经理 · 入门测评师",c:"#D98B4E",d:"全流程框架已建立，但部分关键判定还不够扎实。请用右上角「工具包」对照复习 S/A 矩阵、取高原则与方案六要素，然后重新挑战薄弱关卡。"};
  return {t:"见习项目经理 · 继续深造",c:"#8FA7C3",d:"流程走通了，但知识点掌握还不牢固。建议先完整复习课件 1.1、1.2、2.1、2.2，再回来重新挑战——每一关都有知识点讲解，好好利用。"};
}
function openReport(){
  const rk=rankInfo();
  const projLv = records[8] ? esc(records[8].answer) : "第三级（S3A3）";
  let rows="";
  STEPS.forEach((s,i)=>{
    const r=records[i]||{stars:0,score:0,answer:"未作答"};
    rows+=`<tr><td>${i+1}</td><td>${s.title}</td><td class="st${r.stars}">${r.stars}星</td><td class="mono">${r.score}</td><td title="${esc(r.answer)}">${esc(r.answer.length>40?r.answer.slice(0,40)+"…":r.answer)}</td></tr>`;
  });
  const c3=Object.values(records).filter(r=>r&&r.stars===3).length;
  const c2=Object.values(records).filter(r=>r&&r.stars===2).length;
  const c1=Object.values(records).filter(r=>r&&r.stars===1).length;
  $("reportBody").innerHTML=`
    <div class="report-hero">
      <span class="rh-badge">项目交付 · 通关结算</span>
      <div class="rh-title">等保测评项目交付报告</div>
      <div class="rh-sub">XX市政务服务中心综合管理平台 · 等级保护测评（第三级 S3A3）</div>
      <div class="report-score">
        <div class="rs-box g"><div class="n">${c3}</div><div class="l">三星关卡</div></div>
        <div class="rs-box c"><div class="n">${c2}</div><div class="l">两星关卡</div></div>
        <div class="rs-box p"><div class="n">${c1}</div><div class="l">一星关卡</div></div>
        <div class="rs-box"><div class="n">${score}<span style="font-size:13px;color:#8FA7C3"> / 200</span></div><div class="l">总得分</div></div>
      </div>
      <div style="display:inline-block;margin-top:8px;padding:8px 22px;border:1px solid ${rk.c};border-radius:999px;color:${rk.c};font-weight:800;font-size:15px">${rk.t}</div>
    </div>
    <div class="rank-card">
      <div class="rc-lb">项目经理评语</div>
      <p>${rk.d}</p>
    </div>
    <h4>项目基本信息</h4>
    <table class="kv-table">
      <tr><td>项目名称</td><td>政务服务中心综合管理平台等保测评</td></tr>
      <tr><td>委托单位</td><td>XX市政务服务管理局</td></tr>
      <tr><td>被测系统</td><td>政务服务中心综合管理平台（六大业务模块）</td></tr>
      <tr><td>安全保护等级</td><td>${projLv}</td></tr>
      <tr><td>测评依据</td><td>GB/T 22239-2019、GB/T 28448-2019、GB/T 28449-2018</td></tr>
      <tr><td>项目阶段</td><td>测评准备 → 方案编制 → 现场测评 → 报告编制（已闭环）</td></tr>
    </table>
    <h4>各关卡作答明细</h4>
    <table class="report-table">
      <tr><th>关</th><th>关卡名称</th><th>星级</th><th>得分</th><th>我的答案</th></tr>
      ${rows}
    </table>
    <h4>知识要点回顾</h4>
    <div class="teach-card">
      <p>· 等保五步走：定级 → 备案 → 建设整改 → 等级测评 → 监督检查；测评机构承担第 4 步。</p>
      <p>· 定级口诀：先定对象 · 再评 S/A · 取高者 · 专家审 · 报备案；S 看数据、A 看服务，最终等级 = max(S,A)。</p>
      <p>· 测评四阶段：测评准备 → 方案编制 → 现场测评 → 报告编制。</p>
      <p>· 方案六要素：项目概述、测评范围、测评对象、测评指标、测评方法、日程与人员。</p>
      <p>· 对象四原则：应测尽测、关键性、代表性、抽样（≥30%）；方法三要素：访谈、核查、测试。</p>
      <p>· 报告三核心：单项判定（符合/不符合/部分符合/不适用）、整体结论、整改建议；三级审核后交付。</p>
    </div>
    <div class="modal-actions">
      <button class="btn-primary" id="btnCopyReport">复制报告文本</button>
      <button class="btn-ghost" data-close="reportMask">关闭</button>
      <button class="btn-reset" id="btnRestart">重新挑战</button>
    </div>`;
  $("reportMask").classList.remove("hidden");
  $("btnCopyReport").addEventListener("click",copyReport);
  $("btnRestart").addEventListener("click",resetGame);
}
function copyReport(){
  const rk=rankInfo();
  const c3=Object.values(records).filter(r=>r&&r.stars===3).length;
  const c2=Object.values(records).filter(r=>r&&r.stars===2).length;
  const c1=Object.values(records).filter(r=>r&&r.stars===1).length;
  let lines=["【等保测评项目经理实战 · 交付报告】","项目：政务服务中心综合管理平台等保测评（第三级 S3A3）","","各关卡成绩："];
  STEPS.forEach((s,i)=>{
    const r=records[i]||{stars:0,score:0,answer:"未作答"};
    lines.push(`${i+1}. ${s.title} — ${r.stars}星（${r.score}分）— ${r.answer}`);
  });
  lines.push("","总得分："+score+"/200","评级："+rk.t+"　三星关卡"+c3+"关 / 两星"+c2+"关 / 一星"+c1+"关");
  const txt=lines.join("\n");
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(txt).then(()=>toast("报告文本已复制到剪贴板")).catch(()=>fallbackCopy(txt));
  }else{fallbackCopy(txt);}
}
function fallbackCopy(txt){
  const ta=document.createElement("textarea");
  ta.value=txt; ta.style.position="fixed"; ta.style.opacity="0";
  document.body.appendChild(ta); ta.select();
  try{document.execCommand("copy");toast("报告文本已复制到剪贴板");}catch(e){toast("复制失败，请手动选择文本");}
  document.body.removeChild(ta);
}

// ============ 持久化 ============
function save(){
  try{localStorage.setItem(SAVE_KEY,JSON.stringify({current,score,submitted,records}));}catch(e){}
}
function loadSave(){
  try{
    const raw=localStorage.getItem(SAVE_KEY);
    if(!raw)return false;
    const d=JSON.parse(raw);
    if(!d||typeof d.current!=="number")return false;
    current=Math.min(d.current,STEPS.length-1); score=d.score||0; submitted=!!d.submitted; records=d.records||{};
    return true;
  }catch(e){return false;}
}
function resetGame(){
  if(!confirm("确定要重新开始吗？当前进度与成绩将全部清除。"))return;
  try{localStorage.removeItem(SAVE_KEY);}catch(e){}
  current=0;score=0;submitted=false;records={};
  $("reportMask").classList.add("hidden");$("reviewMask").classList.add("hidden");
  renderStep();
  toast("已重置，重新开始");
}

// ============ 事件绑定 ============
function bind(){
  $("btnStart").addEventListener("click",()=>{
    $("screen-cover").classList.add("hidden");
    $("screen-game").classList.remove("hidden");
    renderStep();
  });
  $("btnHow").addEventListener("click",()=>$("coverHelp").classList.toggle("hidden"));
  $("btnHint").addEventListener("click",()=>$("hintText").classList.toggle("show"));
  $("btnSubmit").addEventListener("click",onSubmit);
  $("answerInput").addEventListener("keydown",e=>{ if((e.ctrlKey||e.metaKey)&&e.key==="Enter")onSubmit(); });
  $("btnReset").addEventListener("click",resetGame);
  $("toolkitToggle").addEventListener("click",()=>$("toolkit").classList.toggle("hidden"));
  $("toolkitClose").addEventListener("click",()=>$("toolkit").classList.add("hidden"));
  document.querySelectorAll("[data-close]").forEach(b=>{
    b.addEventListener("click",()=>$(b.dataset.close).classList.add("hidden"));
  });
  $("reviewMask").addEventListener("click",e=>{if(e.target===$("reviewMask"))$("reviewMask").classList.add("hidden");});
  $("reportMask").addEventListener("click",e=>{if(e.target===$("reportMask"))$("reportMask").classList.add("hidden");});
}
document.addEventListener("DOMContentLoaded",()=>{
  bind();
  if(loadSave()){
    $("screen-cover").classList.add("hidden");
    $("screen-game").classList.remove("hidden");
    renderStep();
    if(submitted&&records[current]){renderFeedback(records[current],true);}
  }
});

